insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-001', 'mcq', 'MAT', 2, 1, null, 1, '1'::jsonb, '{"q":"In which town was Jesus born?","options":["Nazareth","Bethlehem","Jerusalem","Capernaum"],"explain":"Jesus was born in Bethlehem of Judaea, in the days of Herod the king."}'::jsonb, '{"q":"இயேசு எந்த ஊரில் பிறந்தார்?","options":["நாசரேத்","பெத்லகேம்","எருசலேம்","கப்பர்நகூம்"],"explain":"ஏரோது ராஜாவின் நாட்களில் யூதேயாவிலுள்ள பெத்லகேமிலே இயேசு பிறந்தார்."}'::jsonb, 'star', array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-002', 'mcq', 'MAT', 4, 2, null, 1, '3'::jsonb, '{"q":"How many days did Jesus fast in the wilderness?","options":["Seven","Twelve","Thirty","Forty"],"explain":"He fasted forty days and forty nights, and was afterward hungry."}'::jsonb, '{"q":"இயேசு வனாந்தரத்தில் எத்தனை நாள் உபவாசித்தார்?","options":["ஏழு","பன்னிரண்டு","முப்பது","நாற்பது"],"explain":"இரவும் பகலும் நாற்பது நாள் உபவாசமாயிருந்த பின்பு அவருக்குப் பசியுண்டாயிற்று."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-003', 'mcq', 'MAT', 10, 2, null, 1, '2'::jsonb, '{"q":"How many apostles did Jesus choose?","options":["Seven","Ten","Twelve","Seventy"]}'::jsonb, '{"q":"இயேசு எத்தனை அப்போஸ்தலரைத் தெரிந்துகொண்டார்?","options":["ஏழு","பத்து","பன்னிரண்டு","எழுபது"]}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-004', 'who', 'MAT', 16, 16, null, 1, '1'::jsonb, '{"q":"\"Thou art the Christ, the Son of the living God.\"","options":["John","Peter","Thomas","Andrew"],"explain":"Simon Peter answered when Jesus asked, \"Whom say ye that I am?\""}'::jsonb, '{"q":"\"நீர் ஜீவனுள்ள தேவனுடைய குமாரனாகிய கிறிஸ்து.\"","options":["யோவான்","பேதுரு","தோமா","அந்திரேயா"],"explain":"\"நான் யார் என்று சொல்லுகிறீர்கள்?\" என்று இயேசு கேட்டபோது சீமோன் பேதுரு இப்படிப் பதில் சொன்னான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-005', 'mcq', 'MAT', 3, 13, null, 1, '0'::jsonb, '{"q":"Who baptized Jesus in the Jordan?","options":["John the Baptist","Peter","Andrew","James"]}'::jsonb, '{"q":"யோர்தானில் இயேசுவுக்கு ஞானஸ்நானம் கொடுத்தவர் யார்?","options":["யோவான்ஸ்நானன்","பேதுரு","அந்திரேயா","யாக்கோபு"]}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-006', 'mcq', 'MAT', 14, 29, null, 1, '1'::jsonb, '{"q":"Which disciple walked on the water toward Jesus?","options":["John","Peter","James","Matthew"],"explain":"Peter walked on the water, but when he saw the wind he was afraid and began to sink."}'::jsonb, '{"q":"இயேசுவினிடத்திற்குப் போக ஜலத்தின்மேல் நடந்த சீஷன் யார்?","options":["யோவான்","பேதுரு","யாக்கோபு","மத்தேயு"],"explain":"பேதுரு ஜலத்தின்மேல் நடந்தான்; காற்று பலமாயிருக்கிறதைக் கண்டு பயந்து அமிழ்ந்துபோகத் தொடங்கினான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-007', 'tf', 'MAT', 14, 17, null, 2, 'false'::jsonb, '{"q":"Jesus fed the five thousand with seven loaves and two fish.","explain":"False. It was five loaves and two fish."}'::jsonb, '{"q":"இயேசு ஏழு அப்பங்களாலும் இரண்டு மீன்களாலும் ஐயாயிரம் பேரைப் போஷித்தார்.","explain":"தவறு. ஐந்து அப்பங்களும் இரண்டு மீன்களும்."}'::jsonb, 'loaves', array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('mat-008', 'tf', 'MAT', 26, 15, null, 1, 'true'::jsonb, '{"q":"Judas betrayed Jesus for thirty pieces of silver.","explain":"They covenanted with him for thirty pieces of silver."}'::jsonb, '{"q":"யூதாஸ் முப்பது வெள்ளிக்காசுக்கு இயேசுவைக் காட்டிக்கொடுத்தான்.","explain":"அவர்கள் அவனுக்கு முப்பது வெள்ளிக்காசைக் கொடுக்கச் சம்மதித்தார்கள்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('luk-001', 'tf', 'LUK', 19, 4, null, 1, 'true'::jsonb, '{"q":"Zacchaeus climbed a sycomore tree to see Jesus.","explain":"He was little of stature, so he ran ahead and climbed up into a sycomore tree."}'::jsonb, '{"q":"இயேசுவைப் பார்க்கும்படி சகேயு ஒரு காட்டத்திமரத்தில் ஏறினான்.","explain":"அவன் குள்ளனாயிருந்தபடியால் முன்னாக ஓடி ஒரு காட்டத்திமரத்தில் ஏறினான்."}'::jsonb, 'tree', array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('luk-002', 'mcq', 'LUK', 15, 13, null, 1, '1'::jsonb, '{"q":"In the parable, what did the younger son do with his inheritance?","options":["Saved it","Wasted it in riotous living","Gave it to the poor","Buried it in a field"]}'::jsonb, '{"q":"உவமையில் இளைய குமாரன் தன் ஆஸ்தியை என்ன செய்தான்?","options":["சேமித்து வைத்தான்","துன்மார்க்கமாய் ஜீவனம்பண்ணி அழித்தான்","ஏழைகளுக்குக் கொடுத்தான்","நிலத்தில் புதைத்து வைத்தான்"]}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('luk-003', 'book', 'LUK', 10, 33, null, 2, '2'::jsonb, '{"q":"Which Gospel contains the parable of the Good Samaritan?","options":["Matthew","Mark","Luke","John"]}'::jsonb, '{"q":"நல்ல சமாரியனின் உவமை எந்தச் சுவிசேஷத்தில் உள்ளது?","options":["மத்தேயு","மாற்கு","லூக்கா","யோவான்"]}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('jhn-001', 'mcq', 'JHN', 2, 11, null, 1, '1'::jsonb, '{"q":"What was the first miracle Jesus did, at Cana?","options":["Walking on water","Turning water into wine","Feeding the five thousand","Healing a blind man"]}'::jsonb, '{"q":"இயேசு கானாவில் செய்த முதலாம் அற்புதம் எது?","options":["ஜலத்தின்மேல் நடந்தது","தண்ணீரைத் திராட்சரசமாக்கியது","ஐயாயிரம் பேரைப் போஷித்தது","குருடனுக்குப் பார்வை கொடுத்தது"]}'::jsonb, null, array[]::text[], 'published')
