insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('jhn-003', 'who', 'JHN', 20, 28, null, 2, '2'::jsonb, '{"q":"\"My Lord and my God.\"","options":["Peter","Philip","Thomas","Mary Magdalene"],"explain":"Thomas said this when he saw the risen Jesus."}'::jsonb, '{"q":"\"என் ஆண்டவரே! என் தேவனே!\"","options":["பேதுரு","பிலிப்பு","தோமா","மகதலேனா மரியாள்"],"explain":"உயிர்த்தெழுந்த இயேசுவைக் கண்டபோது தோமா இப்படிச் சொன்னான்."}'::jsonb, null, array[]::text[], 'published')
