insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('gen-001', 'mcq', 'GEN', 1, 3, 5, 1, '0'::jsonb, '{"q":"On which day did God create light?","options":["The first day","The second day","The third day","The fourth day"],"explain":"God said, \"Let there be light\" — and the evening and the morning were the first day."}'::jsonb, '{"q":"தேவன் வெளிச்சத்தை எந்த நாளில் உண்டாக்கினார்?","options":["முதலாம் நாள்","இரண்டாம் நாள்","மூன்றாம் நாள்","நான்காம் நாள்"],"explain":"\"வெளிச்சம் உண்டாகக்கடவது\" என்றார்; சாயங்காலமும் விடியற்காலமுமாகி முதலாம் நாள் ஆயிற்று."}'::jsonb, null, array[]::text[], 'published')
