insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('gen-003', 'tf', 'GEN', 7, 12, null, 1, 'true'::jsonb, '{"q":"During the flood, it rained for forty days and forty nights.","explain":"Rain fell upon the earth forty days and forty nights."}'::jsonb, '{"q":"ஜலப்பிரளயத்தின்போது நாற்பது நாள் இரவும் பகலும் மழை பெய்தது.","explain":"நாற்பது நாள் இரவும் பகலும் பூமியின்மேல் பெருமழை பெய்தது."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('gen-004', 'who', 'GEN', 4, 9, null, 1, '1'::jsonb, '{"q":"\"Am I my brother''s keeper?\"","options":["Abel","Cain","Seth","Lamech"],"explain":"Cain said this when God asked him where Abel was."}'::jsonb, '{"q":"\"நான் என் தம்பிக்குக் காவலாளியோ?\"","options":["ஆபேல்","காயீன்","சேத்","லாமேக்கு"],"explain":"ஆபேல் எங்கே என்று தேவன் கேட்டபோது காயீன் இப்படிச் சொன்னான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('gen-005', 'mcq', 'GEN', 37, 3, null, 1, '2'::jsonb, '{"q":"Which son did Jacob give a coat of many colours?","options":["Reuben","Benjamin","Joseph","Judah"],"explain":"Israel loved Joseph more than all his children and made him a coat of many colours."}'::jsonb, '{"q":"யாக்கோபு பலவருணமான அங்கியை எந்தக் குமாரனுக்குக் கொடுத்தான்?","options":["ரூபன்","பென்யமீன்","யோசேப்பு","யூதா"],"explain":"இஸ்ரவேல் தன் குமாரர் எல்லாரிலும் யோசேப்பை அதிகமாய் நேசித்து, அவனுக்குப் பலவருணமான அங்கியைச் செய்வித்தான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('exo-001', 'book', 'EXO', 20, null, null, 1, '1'::jsonb, '{"q":"In which book are the Ten Commandments first given?","options":["Genesis","Exodus","Leviticus","Deuteronomy"],"explain":"Exodus 20. They are repeated in Deuteronomy 5."}'::jsonb, '{"q":"பத்துக் கற்பனைகள் முதன்முதலில் எந்தப் புஸ்தகத்தில் கொடுக்கப்பட்டன?","options":["ஆதியாகமம்","யாத்திராகமம்","லேவியராகமம்","உபாகமம்"],"explain":"யாத்திராகமம் 20. உபாகமம் 5-இல் மறுபடியும் சொல்லப்பட்டுள்ளன."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('exo-002', 'mcq', 'EXO', 7, null, null, 1, '1'::jsonb, '{"q":"How many plagues did God send on Egypt?","options":["Seven","Ten","Twelve","Forty"],"explain":"Ten plagues, from water turned to blood to the death of the firstborn (Exodus 7–12)."}'::jsonb, '{"q":"தேவன் எகிப்தின்மேல் எத்தனை வாதைகளை அனுப்பினார்?","options":["ஏழு","பத்து","பன்னிரண்டு","நாற்பது"],"explain":"இரத்தமான தண்ணீர் முதல் தலைப்பிள்ளைகளின் சங்காரம் வரை பத்து வாதைகள் (யாத்திராகமம் 7–12)."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('exo-003', 'tf', 'EXO', 3, 2, null, 1, 'true'::jsonb, '{"q":"God spoke to Moses from a burning bush.","explain":"The bush burned with fire, and the bush was not consumed."}'::jsonb, '{"q":"தேவன் எரிகிற முட்செடியிலிருந்து மோசேயோடு பேசினார்.","explain":"முட்செடி அக்கினியால் எரிந்தும், அது வெந்துபோகவில்லை."}'::jsonb, 'bush', array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('exo-004', 'tf', 'EXO', 16, 35, null, 2, 'true'::jsonb, '{"q":"The Israelites ate manna in the wilderness for forty years.","explain":"They ate manna forty years, until they came to the border of Canaan."}'::jsonb, '{"q":"இஸ்ரவேலர் வனாந்தரத்தில் நாற்பது வருஷம் மன்னாவைப் புசித்தார்கள்.","explain":"கானான் தேசத்தின் எல்லைக்கு வருமட்டும் நாற்பது வருஷம் மன்னாவைப் புசித்தார்கள்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('jos-001', 'mcq', 'JOS', 6, null, null, 1, '0'::jsonb, '{"q":"Which city''s walls fell after the Israelites marched around it?","options":["Jericho","Ai","Jerusalem","Nineveh"],"explain":"They marched around Jericho for seven days, and the wall fell down flat."}'::jsonb, '{"q":"இஸ்ரவேலர் சுற்றி நடந்த பின்பு எந்தப் பட்டணத்தின் அலங்கம் விழுந்தது?","options":["எரிகோ","ஆயி","எருசலேம்","நினிவே"],"explain":"ஏழு நாள் எரிகோவைச் சுற்றி நடந்தார்கள்; அலங்கம் இடிந்து விழுந்தது."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('jdg-001', 'tf', 'JDG', 16, 17, null, 1, 'false'::jsonb, '{"q":"Samson''s strength was in his sword.","explain":"False. Samson was a Nazarite; his strength was tied to his uncut hair."}'::jsonb, '{"q":"சிம்சோனின் பலம் அவனுடைய பட்டயத்தில் இருந்தது.","explain":"தவறு. சிம்சோன் நசரேயனாயிருந்தான்; அவன் பலம் சிரைக்கப்படாத தலைமயிரோடு இணைந்திருந்தது."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('rut-001', 'who', 'RUT', 1, 16, null, 2, '2'::jsonb, '{"q":"\"Thy people shall be my people, and thy God my God.\"","options":["Naomi","Orpah","Ruth","Boaz"],"explain":"Ruth said this to her mother-in-law Naomi."}'::jsonb, '{"q":"\"உம்முடைய ஜனம் என்னுடைய ஜனம்; உம்முடைய தேவன் என்னுடைய தேவன்.\"","options":["நகோமி","ஒர்பாள்","ரூத்","போவாஸ்"],"explain":"ரூத் தன் மாமியாகிய நகோமியிடம் இப்படிச் சொன்னாள்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('1sa-001', 'who', '1SA', 3, 10, null, 2, '1'::jsonb, '{"q":"\"Speak; for thy servant heareth.\"","options":["Eli","Samuel","Saul","David"],"explain":"The boy Samuel answered when the LORD called him in the night."}'::jsonb, '{"q":"\"சொல்லும், அடியேன் கேட்கிறேன்.\"","options":["ஏலி","சாமுவேல்","சவுல்","தாவீது"],"explain":"இரவில் கர்த்தர் கூப்பிட்டபோது சிறுவனாகிய சாமுவேல் இப்படிப் பதில் சொன்னான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('1sa-002', 'tf', '1SA', 16, 11, null, 1, 'false'::jsonb, '{"q":"David was the oldest son of Jesse.","explain":"False. David was the youngest, keeping the sheep."}'::jsonb, '{"q":"தாவீது ஈசாயின் மூத்த குமாரன்.","explain":"தவறு. தாவீது இளையவன்; ஆடுகளை மேய்த்துக்கொண்டிருந்தான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('1sa-003', 'mcq', '1SA', 17, 49, null, 1, '1'::jsonb, '{"q":"With what did David defeat Goliath?","options":["A sword","A sling and a stone","A spear","A bow"],"explain":"David slung a stone and struck the Philistine in his forehead."}'::jsonb, '{"q":"தாவீது கோலியாத்தை எதைக்கொண்டு வீழ்த்தினான்?","options":["பட்டயம்","கவணும் கல்லும்","ஈட்டி","வில்"],"explain":"தாவீது கவணால் கல்லை எறிந்து, பெலிஸ்தனுடைய நெற்றியில் அடித்தான்."}'::jsonb, 'sling', array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('1sa-004', 'mcq', '1SA', 17, 40, null, 2, '1'::jsonb, '{"q":"How many smooth stones did David choose from the brook?","options":["Three","Five","Seven","Twelve"],"explain":"He chose five smooth stones and put them in his shepherd''s bag."}'::jsonb, '{"q":"தாவீது ஆற்றிலிருந்து எத்தனை கூழாங்கற்களைத் தெரிந்துகொண்டான்?","options":["மூன்று","ஐந்து","ஏழு","பன்னிரண்டு"],"explain":"ஐந்து கூழாங்கற்களைத் தெரிந்துகொண்டு, தன் மேய்ப்பனின் பையிலே போட்டான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('1ki-001', 'mcq', '1KI', 3, 9, null, 1, '2'::jsonb, '{"q":"What did Solomon ask God for?","options":["Riches","A long life","An understanding heart","Victory over enemies"],"explain":"Solomon asked for an understanding heart to judge the people."}'::jsonb, '{"q":"சாலொமோன் தேவனிடத்தில் எதைக் கேட்டான்?","options":["ஐசுவரியம்","நீடிய ஆயுள்","ஞானமுள்ள இருதயம்","சத்துருக்களின்மேல் ஜெயம்"],"explain":"ஜனங்களை நியாயம் விசாரிக்கும்படி ஞானமுள்ள இருதயத்தைக் கேட்டான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('2ki-001', 'mcq', '2KI', 2, 11, null, 2, '0'::jsonb, '{"q":"How was Elijah taken up to heaven?","options":["By a whirlwind, with a chariot of fire","In a dream","On a cloud","By a ladder"],"explain":"A chariot of fire appeared, and Elijah went up by a whirlwind into heaven."}'::jsonb, '{"q":"எலியா எப்படி வானத்துக்கு எடுத்துக்கொள்ளப்பட்டான்?","options":["அக்கினி இரதத்தோடு சுழல்காற்றில்","சொப்பனத்தில்","மேகத்தின்மேல்","ஏணியின் வழியாய்"],"explain":"அக்கினி இரதம் தோன்றியது; எலியா சுழல்காற்றிலே பரலோகத்துக்கு ஏறிப்போனான்."}'::jsonb, null, array[]::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('est-001', 'book', 'EST', 4, 16, null, 2, '1'::jsonb, '{"q":"Which book tells of a queen who said, \"If I perish, I perish\"?","options":["Ruth","Esther","Judges","Daniel"],"explain":"Queen Esther, before going to the king to save her people."}'::jsonb, '{"q":"\"நான் செத்தாலும் சாகிறேன்\" என்று சொன்ன ராஜஸ்திரீயைப் பற்றிச் சொல்லும் புஸ்தகம் எது?","options":["ரூத்","எஸ்தர்","நியாயாதிபதிகள்","தானியேல்"],"explain":"தன் ஜனத்தைக் காப்பாற்ற ராஜாவினிடத்தில் போகுமுன் எஸ்தர் ராணி இப்படிச் சொன்னாள்."}'::jsonb, null, array[]::text[], 'published')
